    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); c=[]
                while q:
                    y,x=q.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append(c)
    return out
def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cs=comps(g,bg); objs=[c for c in cs if len(c)>1]; singles=[c[0] for c in cs if len(c)==1]
    out=[r[:] for r in g]
    for sc2 in singles:
        cv=g[sc2[0]][sc2[1]]
        src=[o for o in objs if cv in Counter(g[y][x] for y,x in o)][0]
        omk=min(src,key=lambda p:g[p[0]][p[1]])
        shp={ (py-omk[0],pq-omk[1]):g[py][pq] for py,pq in src}
        for (dr,dc),v in shp.items():
            yy,xx=sc2[0]+(omk[0]-sc2[0])+dr, sc2[1]+(omk[1]-sc2[1])+dc
            if 0<=yy<H and 0<=xx<W: out[yy][xx]=v
    return out
